'use strict';
(function(root){
const M=root.CloudModel, RAD=Math.PI/180;
const $=id=>document.getElementById(id);
class CloudSimulation{
 constructor(){this.bundle=null;this.elapsed=0;this.playing=false;this.enabled=false;this.minutesPerSecond=5;this.heightScale=25;this.layer='all';this.revision=0;this.abort=null;this.loading=false;this.lastUI=0;this.visiblePoints=[];this.bind();}
 bind(){ $('cloudPlay').onclick=()=>{if(!this.bundle)return;if(this.elapsed>=10800)this.elapsed=0;this.playing=!this.playing;this.updateUI();};$('cloudReset').onclick=()=>{this.elapsed=0;this.updateUI();};$('cloudTime').oninput=e=>{this.playing=false;this.elapsed=Number(e.target.value)*60;this.updateUI();};$('cloudSpeed').onchange=e=>this.minutesPerSecond=Number(e.target.value);$('cloudHeight').oninput=e=>{this.heightScale=Number(e.target.value);$('cloudHeightValue').textContent=this.heightScale+'×';};$('cloudLayer').onchange=e=>{this.layer=e.target.value;this.selectLayer();};$('refreshClouds').onclick=()=>this.refresh();this.loadBundled();}
 async loadBundled(){try{const bundle=root.GeoData?await root.GeoData.amv():root.GEO_AMV_SNAPSHOT;if(bundle)this.apply(bundle,'同梱の観測風');else $('cloudStatus').textContent='観測風がありません。「観測風を更新」を押してください。';}catch(e){$('cloudStatus').textContent='保存した観測風を読み込めません。更新してください。';}}
 apply(bundle,label){M.validateBundle(bundle);this.bundle=bundle;this.elapsed=0;this.playing=!matchMedia('(prefers-reduced-motion: reduce)').matches;this.selectLayer();const iso=M.timeISO(bundle.time);$('cloudObserved').dateTime=iso;$('cloudObserved').textContent=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso))+' 日本時間';const age=(Date.now()-Date.parse(iso))/3600000;$('cloudStatus').textContent=label+(age>6?'（6時間以上前の観測）':'')+'を使用中';$('cloudPlay').disabled=false;$('cloudTime').disabled=false;this.updateUI();}
 selectLayer(){this.visiblePoints=(this.bundle?.points||[]).filter(p=>this.layer==='all'||p.product===this.layer);this.revision++;$('cloudCount').textContent=this.visiblePoints.length.toLocaleString()+' 地点';this.updateUI();}
 updateUI(){ $('cloudPlay').textContent=this.playing?'❚❚ 一時停止':'▶ 雲を動かす';$('cloudPlay').setAttribute('aria-pressed',String(this.playing));$('cloudTime').value=String(this.elapsed/60);$('cloudElapsed').textContent='計算開始から '+Math.floor(this.elapsed/3600)+'時間 '+String(Math.floor(this.elapsed%3600/60)).padStart(2,'0')+'分';$('cloudProgress').textContent=this.elapsed>=10800?'3時間の移動計算が終了しました。初期位置に戻して再開できます。':'観測風を固定した移動計算 · 予報ではありません';}
 tick(dt){if(this.enabled&&this.playing&&this.bundle){this.elapsed=Math.min(10800,this.elapsed+Math.min(dt,.1)*this.minutesPerSecond*60);if(this.elapsed>=10800)this.playing=false;}this.lastUI+=dt;if(this.lastUI>.15){this.lastUI=0;this.updateUI();}}
 async getJSON(url,signal){const response=await fetch(url,{mode:'cors',credentials:'omit',signal});if(!response.ok)throw Error('HTTP '+response.status);return response.json();}
 async refresh(){if(this.loading)return;this.loading=true;this.abort?.abort();this.abort=new AbortController();const signal=this.abort.signal;const timeout=setTimeout(()=>this.abort.abort(),90000);$('refreshClouds').disabled=true;$('cloudStatus').textContent='最新の観測風を確認中…';try{const base='https://realearth.ssec.wisc.edu/api/';const metadata=await this.getJSON(base+'products?'+new URLSearchParams({products:M.PRODUCTS.join(','),timespan:'-6h'}),signal);const time=M.latestCommon(metadata);if(this.bundle?.time===time){$('cloudStatus').textContent='取得可能な最新の観測風です。';return;}const all=[],counts=[];for(const [index,product] of M.PRODUCTS.entries()){$('cloudStatus').textContent=`観測風の数値を取得中 ${index+1}/2…`;const collection=await this.getJSON(base+'shapes?'+new URLSearchParams({products:product+'_'+time.replace('.','_')}),signal);const result=M.normalize(collection,product,time);all.push(...result.points);counts.push({product,selected:result.points.length,matching:result.matching,old:result.old,invalid:result.invalid});}if(!signal.aborted)this.apply({time,points:all,counts,source:'SSEC RealEarth, UW-Madison'},'取得した観測風');}catch(e){$('cloudStatus').textContent=this.bundle?'更新できませんでした。表示中の日時の観測風で計算を続けます。':'観測風を取得できませんでした。接続を確認してください。';}finally{clearTimeout(timeout);this.loading=false;$('refreshClouds').disabled=false;}}
}
class CloudRenderer{
 constructor(gl,simulation){this.gl=gl;this.sim=simulation;this.revision=-1;this.items=[];this.buffer=gl.createBuffer();this.data=new Float32Array(0);this.maxPoint=gl.getParameter(gl.ALIASED_POINT_SIZE_RANGE)[1];
 const vs=`precision highp float;
 attribute vec3 center;attribute vec3 radii;attribute float seed;
 uniform vec2 resolution;uniform float yaw,pitch,zoom,maxPoint;
 varying vec3 c;varying vec3 rad;varying float pattern;
 vec3 toView(vec3 q){float cy=cos(yaw),sy=sin(yaw),cp=cos(pitch),sp=sin(pitch);float x=q.x*cy-q.z*sy;float z=q.x*sy+q.z*cy;return vec3(x,q.y*cp-z*sp,q.y*sp+z*cp);}
 void main(){c=toView(center);rad=radii;pattern=seed;float s=min(resolution.x,resolution.y)*zoom*.77;gl_Position=vec4(c.xy*s/resolution,0.,1.);gl_PointSize=min(maxPoint,max(max(radii.x,radii.y),radii.z)*s*2.2);}`;
 // Ray-march a 3-D procedural density in a tangent-oriented ellipsoid.
 // No satellite raster, animated texture or frame blending drives these clouds.
 const fs=`precision highp float;
 varying vec3 c;varying vec3 rad;varying float pattern;
 uniform vec2 resolution;uniform float yaw,pitch,zoom,mode;
 vec3 toWorld(vec3 n){float cp=cos(pitch),sp=sin(pitch),cy=cos(yaw),sy=sin(yaw);vec3 q=vec3(n.x,n.y*cp+n.z*sp,-n.y*sp+n.z*cp);return vec3(q.x*cy+q.z*sy,q.y,-q.x*sy+q.z*cy);}
 float noise(vec3 p){return .5+.17*sin(p.x*5.+pattern)+.17*sin(p.y*6.-pattern)+.16*sin(p.z*7.+p.x*3.);}
 void main(){vec2 xy=(gl_FragCoord.xy*2.-resolution)/(min(resolution.x,resolution.y)*zoom*.77);float r2=dot(xy,xy);float ground=r2<1.?sqrt(1.-r2):-10.;float bound=max(max(rad.x,rad.y),rad.z)*1.1;if(c.z+bound<ground)discard;vec3 centerWorld=toWorld(c);vec3 up=normalize(centerWorld);vec3 east=normalize(vec3(up.z,0.,-up.x));vec3 north=cross(up,east);float alpha=0.;vec3 color=vec3(0.);for(int i=0;i<14;i++){float z=c.z+bound-(float(i)+.5)*(2.*bound/14.);if(z<ground)continue;vec3 d=toWorld(vec3(xy,z)-c);vec3 local=vec3(dot(d,east),dot(d,north),dot(d,up))/rad;float r=length(local);if(r>1.)continue;float density=(1.-smoothstep(.25,1.,r))*(.5+.5*noise(local));float a=1.-exp(-density*.30);vec3 normal=normalize(toWorld(vec3(xy-c.xy,z-c.z))+.00001);float light=.7+.30*dot(normal,normalize(vec3(-.5,.8,1.)));float sun=mode>.5?.12+.88*smoothstep(-.12,.3,dot(normalize(c),normalize(vec3(-.8,.45,.6)))):1.;vec3 shade=mix(vec3(.60,.70,.80),vec3(1.),clamp(light,0.,1.))*sun;color+=(1.-alpha)*a*shade;alpha+=(1.-alpha)*a;}if(alpha<.005)discard;gl_FragColor=vec4(color/max(alpha,.0001),alpha);}`;
 const compile=(type,code)=>{const s=gl.createShader(type);gl.shaderSource(s,code);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};this.program=gl.createProgram();gl.attachShader(this.program,compile(gl.VERTEX_SHADER,vs));gl.attachShader(this.program,compile(gl.FRAGMENT_SHADER,fs));gl.linkProgram(this.program);if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(this.program));this.attributes=['center','radii','seed'].map(k=>gl.getAttribLocation(this.program,k));this.uniforms={};for(const k of ['resolution','yaw','pitch','zoom','mode','maxPoint'])this.uniforms[k]=gl.getUniformLocation(this.program,k);}
 rebuild(){this.items=[];for(const [index,point] of this.sim.visiblePoints.entries()){for(let j=0;j<2;j++){this.items.push({point,seed:index*2.399+j*7.13,j,x:0,y:0,z:0,depth:0});}}this.data=new Float32Array(this.items.length*7);this.revision=this.sim.revision;}
 draw({width,height,yaw,pitch,zoom,mode}){const gl=this.gl,sim=this.sim;if(!sim.enabled||!sim.bundle)return;if(this.revision!==sim.revision)this.rebuild();const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);for(const item of this.items){const p=M.advect(item.point,sim.elapsed);const lat=(p.lat+(item.j? .18:-.18))*RAD,lon=(p.lon+(item.j?.22:-.22)/Math.max(.2,Math.cos(lat)))*RAD;const radius=1+item.point.altitudeKm/M.EARTH_KM*sim.heightScale;item.x=radius*Math.cos(lat)*Math.sin(lon);item.y=radius*Math.sin(lat);item.z=radius*Math.cos(lat)*Math.cos(lon);item.depth=item.y*sp+(item.x*sy+item.z*cy)*cp;}this.items.sort((a,b)=>a.depth-b.depth);let n=0;for(const item of this.items){if(item.depth<-.05)continue;const widthR=.009+.004*(.5+.5*Math.sin(item.seed));this.data.set([item.x,item.y,item.z,widthR,widthR*.72,.0035+.0015*(item.j+1),item.seed],n*7);n++;}if(!n)return;gl.useProgram(this.program);gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);gl.bufferData(gl.ARRAY_BUFFER,this.data.subarray(0,n*7),gl.DYNAMIC_DRAW);const sizes=[3,3,1],offsets=[0,12,24];for(let i=0;i<3;i++){gl.enableVertexAttribArray(this.attributes[i]);gl.vertexAttribPointer(this.attributes[i],sizes[i],gl.FLOAT,false,28,offsets[i]);}gl.uniform2f(this.uniforms.resolution,width,height);for(const [k,v] of Object.entries({yaw,pitch,zoom,mode,maxPoint:this.maxPoint}))gl.uniform1f(this.uniforms[k],v);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.drawArrays(gl.POINTS,0,n);gl.disable(gl.BLEND);for(const a of this.attributes)gl.disableVertexAttribArray(a);}
}
root.CloudSimulation=CloudSimulation;root.CloudRenderer=CloudRenderer;
})(typeof window==='undefined'?globalThis:window);
